'use strict';
async function albumAdminAPI(body){const store=await TemuStore.read();if(!store.config.token)throw Error('Hubungkan server terlebih dahulu pada Pengaturan.');const response=await fetch('/api/album/admin',{method:body?'POST':'GET',headers:{'Content-Type':'application/json','X-Temu-Album':'1','Authorization':'Bearer '+store.config.token},body:body?JSON.stringify(body):undefined,cache:'no-store'});const result=await response.json();if(!response.ok)throw Error(result.error||'Pengaturan album belum tersedia.');return result.config;}
function albumLocalDate(iso){if(!iso)return '2026-11-21T20:30';const date=new Date(iso);return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function albumShare(config){const url=new URL('/album',location.origin);url.hash='k='+config.key;return url.href;}
async function showAlbumSettings(){if(!await admin())return;try{const config=await albumAdminAPI();modal('Album bersama',`<p>QR album mengajak tamu berbagi foto dan video. QR ini terpisah dari QR check-in.</p><form id="album-config"><label>Nama album<input id="album-title" maxlength="120" value="${esc(config?.title||'Reva & Cesar')}" required></label><label>Galeri dapat dilihat<select id="album-mode"><option value="live" ${config?.mode==='live'?'selected':''}>Selama acara / langsung</option><option value="after" ${config?.mode!=='live'?'selected':''}>Pada tanggal dan jam yang ditentukan</option></select></label><label id="album-date-label">Tanggal dan jam pembukaan (waktu perangkat)<input id="album-release" type="datetime-local" value="${albumLocalDate(config?.releaseAt)}"></label><label>Nuansa awal<select id="album-preset">${[['original','Asli'],['film','Film'],['warm','Hangat'],['mono','Monokrom']].map(([value,label])=>`<option value="${value}" ${value===(config?.filter||'film')?'selected':''}>${label}</option>`).join('')}</select></label><label>Unggahan tamu<select id="album-uploads"><option value="y" ${config?.uploadsOpen!==false?'selected':''}>Dibuka</option><option value="n" ${config?.uploadsOpen===false?'selected':''}>Ditutup</option></select></label><button class="primary wide">${config?'Simpan pengaturan album':'Aktifkan album & buat QR'}</button></form><p class="hint">File asli disimpan di volume server. Batas 100 MB per file dan 2 GB untuk seluruh album. File album perlu ikut disalin saat mencadangkan server.</p><div id="album-share"></div><hr><h3>Kelola foto & video</h3><p>Periksa momen tamu, hapus satu per satu, atau kosongkan album. Pengelola dapat melihatnya meskipun galeri tamu belum dibuka.</p><button id="album-manage" type="button">Kelola isi album</button>`);const mode=$('#album-mode'),date=$('#album-date-label');const update=()=>{date.hidden=mode.value==='live';$('#album-release').required=mode.value==='after';};mode.onchange=update;update();$('#album-manage').onclick=showAlbumManagement;if(config)renderAlbumShare(config);$('#album-config').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const config=await albumAdminAPI({title:$('#album-title').value.trim(),mode:mode.value,releaseAt:mode.value==='after'?new Date($('#album-release').value).toISOString():'',filter:$('#album-preset').value,uploadsOpen:$('#album-uploads').value==='y'});renderAlbumShare(config);toast('Album tersimpan. QR tetap sama setelah pengaturan diperbarui.');}catch(e){toast(e.message);}finally{button.disabled=false;}};}catch(e){toast(e.message);}}
function renderAlbumShare(config){const url=albumShare(config),q=qrcode(0,'M');q.addData(url);q.make();const svg=q.createSvgTag(5,20);$('#album-share').innerHTML=`<div class="qr-preview album-admin-qr"><h3>Bagikan cerita dari mejamu</h3>${svg}<p>#foREVArwithCESAR</p><p class="hint">Pindai QR ini untuk foto, video, dan album bersama.</p><div class="actions"><a class="album-open-link" target="_blank" rel="noopener" href="${esc(url)}">Buka album ↗</a><button id="copy-album-link" type="button">Salin tautan album</button><button id="print-album-qr" type="button">Cetak QR meja</button></div></div>`;$('#copy-album-link').onclick=async()=>{try{await navigator.clipboard.writeText(url);toast('Tautan album disalin.');}catch{modal('Tautan album',`<label>Salin tautan ini<input readonly value="${esc(url)}"></label>`);}};$('#print-album-qr').onclick=()=>{$('#print-area').innerHTML=`<section class="album-qr-print"><span>FROM YOUR TABLE, WITH LOVE</span><h1>Our shared moments.</h1><h2>#foREVArwithCESAR</h2>${svg}<p>Jepret tawa, pelukan, dan cerita kecil hari ini.</p><strong>Pindai untuk berbagi foto & video</strong><p>Tanpa aplikasi · Langsung dari HP kamu</p><small>Made by Cesar with love</small></section>`;window.print();};}
document.querySelector('#album-settings').onclick=showAlbumSettings;
let albumAdminPreviews=[],albumManageVersion=0;
function disposeAlbumPreviews(){albumManageVersion++;albumAdminPreviews.forEach(URL.revokeObjectURL);albumAdminPreviews=[];}
async function albumManageAPI(path='',method='GET',body){
 const store=await TemuStore.read();if(!store.config.token)throw Error('Hubungkan server terlebih dahulu.');
 const r=await fetch('/api/album/admin/'+path,{method,headers:{'Content-Type':'application/json','X-Temu-Album':'1','Authorization':'Bearer '+store.config.token},body:body?JSON.stringify(body):undefined,cache:'no-store',signal:AbortSignal.timeout(30000)});
 const result=await r.json();if(!r.ok)throw Error(result.error||'Album belum dapat dikelola.');return result;
}
async function albumAdminMedia(item,thumb=false){
 const store=await TemuStore.read(),r=await fetch('/api/album/admin/file/'+item.id+(thumb?'?thumb=1':''),{headers:{'Authorization':'Bearer '+store.config.token},cache:'no-store',signal:AbortSignal.timeout(30000)});
 if(!r.ok)throw Error('Momen tidak tersedia. Perbarui album.');return URL.createObjectURL(await r.blob());
}
async function showAlbumManagement(){
 if(!await admin())return;disposeAlbumPreviews();const version=albumManageVersion;
 modal('Kelola album bersama',`<p id="album-manage-status" role="status">Memuat album…</p><div class="actions"><button id="album-manage-refresh">Perbarui</button><button id="album-clear" class="danger" disabled>Hapus semua foto & video</button><button id="album-back-settings">Pengaturan album</button></div><div id="album-admin-grid" class="album-admin-grid"></div><button id="album-admin-more" class="wide" hidden>Lihat lebih banyak</button>`);
 $('#modal').addEventListener('close',disposeAlbumPreviews,{once:true});$('#album-back-settings').onclick=()=>{disposeAlbumPreviews();showAlbumSettings();};$('#album-manage-refresh').onclick=showAlbumManagement;
 let entries=[],next=0,total=0,busy=false;
 async function load(){if(busy)return;busy=true;$('#album-admin-more').disabled=true;try{
  const result=await albumManageAPI('items?offset='+next);if(version!==albumManageVersion)return;total=result.count;entries.push(...result.items);next=result.next;
  $('#album-manage-status').textContent=total+' foto/video tersimpan. Menghapus momen juga menghapus file aslinya. QR dan pengaturan album tetap sama.';$('#album-clear').disabled=total===0;
  albumAdminPreviews.forEach(URL.revokeObjectURL);albumAdminPreviews=[];$('#album-admin-grid').innerHTML=entries.map(item=>`<article class="album-admin-card"><div class="album-admin-preview" data-preview="${item.id}">${item.mime.startsWith('image/')?'◎ Foto':'▷ Video'}</div><h3>${esc(item.name)}</h3><p>${esc(item.caption)}</p><small>${esc(new Date(item.created).toLocaleString('id-ID'))}</small><div class="actions"><button data-view="${item.id}">Lihat</button><button class="danger" data-delete="${item.id}">Hapus</button></div></article>`).join('');$('#album-admin-more').hidden=next===null;
  for(const item of entries.filter(x=>x.thumbnail)){try{const url=await albumAdminMedia(item,true);if(version!==albumManageVersion){URL.revokeObjectURL(url);return;}albumAdminPreviews.push(url);const box=document.querySelector('[data-preview="'+item.id+'"]');box.replaceChildren(Object.assign(document.createElement('img'),{src:url,alt:'Foto dari '+item.name}));}catch{/* Keep a usable card when a preview is unavailable. */}}
 }catch(e){if(version===albumManageVersion)$('#album-manage-status').textContent=e.message;}finally{busy=false;if(version===albumManageVersion)$('#album-admin-more').disabled=false;}}
 $('#album-admin-more').onclick=load;
 $('#album-admin-grid').onclick=async e=>{const del=e.target.closest('[data-delete]'),view=e.target.closest('[data-view]');const item=entries.find(x=>x.id===(del?.dataset.delete||view?.dataset.view));if(!item)return;
  if(view){view.disabled=true;try{const url=await albumAdminMedia(item);if(version!==albumManageVersion){URL.revokeObjectURL(url);return;}disposeAlbumPreviews();albumAdminPreviews.push(url);modal('Momen dari '+item.name,`${item.mime.startsWith('image/')?`<img class="album-admin-detail" src="${url}" alt="Momen tamu">`:`<video class="album-admin-detail" src="${url}" controls playsinline></video>`}<p>${esc(item.caption)}</p><button id="album-list-back">Kembali ke daftar</button>`);$('#album-list-back').onclick=showAlbumManagement;}catch(e){toast(e.message);}finally{view.disabled=false;}return;}
  disposeAlbumPreviews();modal('Hapus momen ini?',`<p>Foto/video dari <strong>${esc(item.name)}</strong> beserta file asli dan pratinjaunya akan dihapus permanen. Tindakan ini tidak dapat dibatalkan.</p><div class="actions"><button id="album-delete-confirm" class="danger">Hapus momen</button><button id="album-delete-cancel">Batal</button></div>`);$('#album-delete-cancel').onclick=showAlbumManagement;$('#album-delete-confirm').onclick=async e=>{e.target.disabled=true;try{await albumManageAPI('items/'+item.id,'DELETE');toast('Momen dihapus.');showAlbumManagement();}catch(e){toast(e.message);}finally{e.target.disabled=false;}};
 };
 $('#album-clear').onclick=()=>{if(!db.pin)return toast('Atur PIN pengelola pada Pengaturan sebelum mengosongkan album.');const count=total,event=db.event.id;disposeAlbumPreviews();modal('Kosongkan album bersama?',`<p><strong>${count} foto/video</strong>, file asli, dan pratinjau akan dihapus permanen. Acara, data tamu, QR, dan pengaturan album tetap tersedia.</p><p class="hint">Tindakan ini tidak dapat dibatalkan. Simpan foto yang masih diperlukan sebelum melanjutkan.</p><form id="album-clear-form"><label>Masukkan kembali PIN pengelola<input id="album-clear-pin" type="password" inputmode="numeric" autocomplete="off" pattern="[0-9]{4,12}" required></label><div class="actions"><button class="danger">Hapus semua foto & video</button><button id="album-clear-cancel" type="button">Batal</button></div></form>`);$('#album-clear-cancel').onclick=showAlbumManagement;$('#album-clear-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await albumManageAPI('items','DELETE',{event,pin:$('#album-clear-pin').value,count});toast('Album dikosongkan. QR album tetap sama.');showAlbumManagement();}catch(error){toast(error.message);button.disabled=false;$('#album-clear-pin').value='';}};};
 load();
}
